"""Static DAG validation and level planning for workflow definitions.

The planner only analyzes dependencies; it never executes tasks. Loading,
JSON decoding, structural validation, graph validation, and normalization
live in the shared :mod:`workflow_orchestrator.graph` core; this module only
turns a validated :class:`~workflow_orchestrator.graph.ValidGraph` into
deterministic execution levels and translates a core failure into the exit
code and diagnostic ``plan`` has always reported.
"""
import json

from .graph import GraphLoadError, load_graph


def build_levels(graph) -> list[list[str]]:
    """Group tasks into levels by deepest dependency.

    A task with no dependencies sits on level 0; every other task is placed
    one level below its deepest dependency. Tasks within a level are ordered
    by Unicode code point. The walk is iterative, so arbitrarily deep DAGs
    do not depend on the Python recursion limit.
    """
    deps_by_task = graph.dependencies

    depth = {}
    for root in graph.tasks:
        if root in depth:
            continue
        stack = [(root, False)]
        while stack:
            node, done = stack.pop()
            if done:
                deps = deps_by_task[node]
                depth[node] = 0 if not deps else 1 + max(depth[d] for d in deps)
            elif node not in depth:
                stack.append((node, True))
                for dep in deps_by_task[node]:
                    if dep not in depth:
                        stack.append((dep, False))

    levels = []
    for task_id, level in depth.items():
        while len(levels) <= level:
            levels.append([])
        levels[level].append(task_id)
    for level in levels:
        level.sort()  # Unicode code point order
    return levels


def render(levels) -> str:
    return json.dumps({"levels": levels}, ensure_ascii=False, separators=(",", ":"))


def run(path: str, stdout, stderr) -> int:
    """Execute the plan command, writing to the provided text streams."""
    try:
        graph = load_graph(path)
    except GraphLoadError as error:
        stderr.write(error.diagnostic + "\n")
        return error.code
    stdout.write(render(build_levels(graph)) + "\n")
    return 0

"""Shared loading, validation, and normalization of workflow definitions.

This module is the single place that touches a definition's raw bytes.
Both the ``plan`` and ``schedule`` commands consume the same
:class:`ValidGraph`; neither re-parses JSON or re-judges graph errors.

The pipeline is split into four strict layers, each with one failure mode:

1. :func:`read_file`       -- file system access (bytes or :class:`CannotRead`)
2. :func:`decode_json`     -- JSON syntax (a JSON value or :class:`InvalidJson`)
3. :func:`parse_definition`-- definition structure (entries or
                              :class:`InvalidDefinition`)
4. :func:`build_graph`     -- graph semantics (a :class:`ValidGraph`, or one
                              deterministically chosen :class:`GraphError`)

:func:`load_graph` runs all four in order. No function in this module reads
from or writes to stdout/stderr; failures are carried by exceptions whose
``code`` and ``diagnostic`` the command entry points turn into exit codes and
diagnostic lines.
"""
import json
from collections import Counter, defaultdict
from types import MappingProxyType
from typing import NamedTuple


# ---------------------------------------------------------------------------
# Failures: a closed hierarchy of deterministic results, no streams involved.
# ---------------------------------------------------------------------------

class GraphLoadError(Exception):
    """Base class for every definition-loading failure.

    Each failure fixes its own process exit ``code`` and the exact
    ``diagnostic`` text (without trailing newline) the commands must print.
    """

    code: int = 2

    @property
    def diagnostic(self) -> str:
        raise NotImplementedError


class CannotRead(GraphLoadError):
    """The definition file could not be read. Exit code 1."""

    code = 1

    def __init__(self, path: str):
        super().__init__(path)
        self.path = path

    @property
    def diagnostic(self) -> str:
        return f"cannot read definition: {self.path}"


class InvalidJson(GraphLoadError):
    """The definition file is not valid JSON (or not valid UTF-8)."""

    @property
    def diagnostic(self) -> str:
        return "invalid json"


class InvalidDefinition(GraphLoadError):
    """The JSON value does not have the required definition structure."""

    @property
    def diagnostic(self) -> str:
        return "invalid definition"


class GraphError(GraphLoadError):
    """The definition is structurally well formed but the graph is invalid."""

    def __init__(self, message: str):
        super().__init__(message)
        self.message = message

    @property
    def diagnostic(self) -> str:
        return self.message


# ---------------------------------------------------------------------------
# The normalized result.
# ---------------------------------------------------------------------------

class ValidGraph(NamedTuple):
    """A read-only, validated, normalized view of a workflow definition.

    ``tasks`` is every task id in Unicode code point order.
    ``dependencies`` maps each task to its de-duplicated dependency ids.
    ``dependents`` is the reverse relation, likewise de-duplicated. Every
    contained mapping is wrapped to reject mutation and every relation is a
    tuple, so consumers cannot alter the shared graph.
    """

    tasks: tuple[str, ...]
    dependencies: MappingProxyType
    dependents: MappingProxyType


# ---------------------------------------------------------------------------
# Layer 1: file system.
# ---------------------------------------------------------------------------

def read_file(path: str) -> bytes:
    """Read the raw definition bytes, or raise :class:`CannotRead`."""
    try:
        with open(path, "rb") as handle:
            return handle.read()
    except OSError as exc:  # missing file, permission denied, directory, ...
        raise CannotRead(path) from exc


# ---------------------------------------------------------------------------
# Layer 2: JSON syntax.
# ---------------------------------------------------------------------------

def decode_json(raw: bytes):
    """Decode JSON bytes, or raise :class:`InvalidJson`.

    ``json.loads`` accepts ``bytes`` and reports invalid UTF-8 as a
    ``ValueError`` alongside syntax errors, so one clause covers both.
    """
    try:
        return json.loads(raw)
    except ValueError as exc:
        raise InvalidJson from exc


# ---------------------------------------------------------------------------
# Layer 3: definition structure.
# ---------------------------------------------------------------------------

def parse_definition(document):
    """Validate the JSON value's shape; return ``[(task_id, [deps]), ...]``.

    Only structural rules live here: the top-level object, the task list,
    field presence/names, and value types. Graph semantics (duplicates,
    unknown/self dependencies, cycles) are deferred to :func:`build_graph`.
    """
    # Top level must be an object containing exactly one key: "tasks".
    if not isinstance(document, dict) or set(document) != {"tasks"}:
        raise InvalidDefinition
    raw_tasks = document["tasks"]
    if not isinstance(raw_tasks, list):
        raise InvalidDefinition

    entries = []
    for task in raw_tasks:
        if not isinstance(task, dict):
            raise InvalidDefinition
        if not set(task) <= {"id", "depends_on"}:
            raise InvalidDefinition
        task_id = task.get("id")
        if not isinstance(task_id, str) or task_id == "":
            raise InvalidDefinition
        depends_on = task.get("depends_on", [])
        if not isinstance(depends_on, list) or not all(
            isinstance(dep, str) for dep in depends_on
        ):
            raise InvalidDefinition
        entries.append((task_id, list(depends_on)))
    return entries


# ---------------------------------------------------------------------------
# Layer 4: graph semantics.
# ---------------------------------------------------------------------------

def _reachable(adj, start):
    """Iterative reachability from ``start`` over ``adj`` (no recursion)."""
    seen = set()
    stack = [start]
    while stack:
        node = stack.pop()
        for nxt in adj.get(node, ()):
            if nxt not in seen:
                seen.add(nxt)
                stack.append(nxt)
    return seen


def select_graph_error(entries):
    """Return the one graph-error message to report, or None if the DAG is valid.

    Every structural graph problem is keyed by the (task id, dependency id)
    pair it involves and candidates are compared by Unicode code point order,
    so the choice never depends on input ordering or hash iteration order.
    """
    counts = Counter(task_id for task_id, _ in entries)
    known = set(counts)

    # (first id, second id, kind rank, message); kind rank only breaks exact
    # pair ties deterministically.
    candidates = []
    for task_id in counts:
        if counts[task_id] > 1:
            candidates.append((task_id, "", 0, f"duplicate task id: {task_id}"))

    adj = defaultdict(set)
    for task_id, deps in entries:
        for dep in set(deps):
            if dep == task_id:
                candidates.append(
                    (task_id, task_id, 1, f"self dependency: {task_id}")
                )
            elif dep not in known:
                candidates.append(
                    (task_id, dep, 2, f"unknown dependency: {task_id} -> {dep}")
                )
            else:
                adj[task_id].add(dep)

    # An edge u -> v (u != v) participates in a cycle iff v can reach u.
    reach_cache = {}
    cycle_key = None
    for task_id, deps in adj.items():
        for dep in deps:
            if dep not in reach_cache:
                reach_cache[dep] = _reachable(adj, dep)
            if task_id in reach_cache[dep]:
                key = (task_id, dep)
                if cycle_key is None or key < cycle_key:
                    cycle_key = key
    if cycle_key is not None:
        candidates.append(
            (cycle_key[0], cycle_key[1], 3, "cycle detected")
        )

    if not candidates:
        return None
    return min(candidates, key=lambda item: item[:3])[3]


def build_graph(entries) -> ValidGraph:
    """Validate graph semantics and normalize valid entries.

    Raises :class:`GraphError` with the single deterministically chosen
    diagnostic when the graph is invalid. Duplicate dependency entries count
    as one. Relations are sorted by Unicode code point order so the result
    depends only on graph content, never on listing or iteration order.
    """
    message = select_graph_error(entries)
    if message is not None:
        raise GraphError(message)

    tasks = tuple(sorted({task_id for task_id, _ in entries}))

    # Build the maps in the canonical (Unicode-sorted) task order so the
    # whole object is independent of how tasks were listed.
    unique_deps = {
        task_id: tuple(sorted(set(deps))) for task_id, deps in entries
    }
    dependencies = MappingProxyType(
        {task_id: unique_deps[task_id] for task_id in tasks}
    )

    dependents = {task_id: [] for task_id in tasks}
    for task_id in tasks:
        for dep in unique_deps[task_id]:
            dependents[dep].append(task_id)

    return ValidGraph(
        tasks=tasks,
        dependencies=dependencies,
        dependents=MappingProxyType(
            {task_id: tuple(dependents[task_id]) for task_id in tasks}
        ),
    )


# ---------------------------------------------------------------------------
# Full pipeline.
# ---------------------------------------------------------------------------

def load_graph(path: str) -> ValidGraph:
    """Read, decode, structurally validate, and semantically validate a file.

    Returns the shared read-only :class:`ValidGraph`. Raises one of the
    :class:`GraphLoadError` subclasses on failure; checks run strictly in the
    order read -> decode -> structure -> graph.
    """
    raw = read_file(path)
    document = decode_json(raw)
    entries = parse_definition(document)
    return build_graph(entries)

"""Shared black-box test infrastructure.

Tests enter through the documented public entry point
(``python -m workflow_orchestrator``) with definition files on disk, and
assert on the process exit status and raw stdout/stderr bytes.

The subprocess environment is whitelisted and pinned so results cannot
depend on the invoking machine's locale, Python hash seed, or directory
ordering:

* ``LC_ALL=LANG=C`` with UTF-8 mode / IO encoding forced on (a test-time
  configuration; the installed library keeps zero runtime dependencies),
* a fixed ``PYTHONHASHSEED`` by default, with dedicated tests varying it,
* ``cwd`` and ``PYTHONPATH`` pinned at the repository root.
"""
import json
import os
import subprocess
import sys
from concurrent.futures import ThreadPoolExecutor

import pytest

REPO_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))

BASE_ENV = {
    "PATH": os.environ.get("PATH", ""),
    "HOME": os.environ.get("HOME", "/tmp"),
    "TMPDIR": os.environ.get("TMPDIR", "/tmp"),
    "LC_ALL": "C",
    "LANG": "C",
    # Pin the standard stream encoding to UTF-8 on every supported Python
    # regardless of the C locale above.
    "PYTHONUTF8": "1",
    "PYTHONIOENCODING": "utf-8",
    "PYTHONHASHSEED": "0",
    "PYTHONPATH": REPO_ROOT,
}


def make_env(**overrides):
    """A subprocess environment based on BASE_ENV.

    A value of None removes the key entirely (e.g. PYTHONHASHSEED=None to
    let the interpreter pick a random seed).
    """
    env = dict(BASE_ENV)
    for key, value in overrides.items():
        if value is None:
            env.pop(key, None)
        else:
            env[key] = value
    return env


class CliRunner:
    """Run the public CLI as a subprocess and capture raw byte streams."""

    def run(self, argv, *, env=None, timeout=120):
        return subprocess.run(
            [sys.executable, "-m", "workflow_orchestrator", *argv],
            cwd=REPO_ROOT,
            env=BASE_ENV if env is None else env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=timeout,
        )

    def plan(self, path, *, env=None, timeout=120):
        return self.run(["plan", str(path)], env=env, timeout=timeout)

    def schedule(self, path, max_parallel, *, env=None, timeout=120):
        return self.run(
            ["schedule", str(path), str(max_parallel)], env=env, timeout=timeout
        )

    def plan_many(self, paths, *, env=None, timeout=120, workers=8):
        """Run plan over many definition files concurrently, in order.

        Subprocess startup dominates these cases; waiting on child processes
        releases the GIL, so a thread pool keeps the suite fast without any
        shared state between runs.
        """
        paths = list(paths)
        with ThreadPoolExecutor(max_workers=workers) as pool:
            return list(
                pool.map(
                    lambda p: self.plan(p, env=env, timeout=timeout), paths
                )
            )


def render_levels(levels) -> bytes:
    """The exact compact success-output byte contract (plus newline)."""
    return (
        json.dumps(
            {"levels": levels}, ensure_ascii=False, separators=(",", ":")
        )
        + "\n"
    ).encode("utf-8")


def render_batches(batches) -> bytes:
    """The exact compact schedule success-output byte contract (plus newline)."""
    return (
        json.dumps(
            {"batches": batches}, ensure_ascii=False, separators=(",", ":")
        )
        + "\n"
    ).encode("utf-8")


@pytest.fixture(scope="session")
def cli():
    return CliRunner()


@pytest.fixture
def write_def(tmp_path):
    """Write a definition document (or raw bytes) and return its path."""
    counter = 0

    def _write(doc=None, *, raw=None, name=None, indent=False):
        nonlocal counter
        path = tmp_path / (name or f"definition-{counter}.json")
        counter += 1
        if raw is not None:
            path.write_bytes(raw)
        else:
            text = json.dumps(doc, ensure_ascii=False, indent=2 if indent else None)
            path.write_text(text, encoding="utf-8")
        return path

    return _write


def assert_success(result, expected_stdout: bytes):
    """Assert the full success contract: rc 0, exact stdout, empty stderr."""
    assert result.returncode == 0, result.stderr
    assert result.stdout == expected_stdout
    assert result.stderr == b""


def assert_failure(result, expected_stderr: bytes, code=2):
    """Assert the full failure contract: given rc, empty stdout, one diagnostic."""
    assert result.returncode == code
    assert result.stdout == b"", "failure path must write nothing to stdout"
    assert result.stderr == expected_stderr
    # Every documented failure reports exactly one line on stderr.
    assert expected_stderr.endswith(b"\n")
    assert expected_stderr.count(b"\n") == 1

